function expDelay(attempt, opts){
  opts=opts||{};
  var base=opts.base||1000, cap=opts.cap||30000, factor=opts.factor||2;
  attempt=(attempt<0?0:attempt)|0;
  return Math.min(cap, Math.round(base*Math.pow(factor, attempt)));
}
function backoff(attempt, opts, rng){
  opts=opts||{};
  var strategy=opts.strategy||'full';
  var base=opts.base||1000, cap=opts.cap||30000, factor=opts.factor||2;
  if(typeof rng!=='function') rng=Math.random;
  var d=expDelay(attempt,{base:base,cap:cap,factor:factor});
  if(strategy==='none') return {base:d, min:d, max:d, value:d, error:null};
  if(strategy==='full'){ var hi=Math.floor(rng()*d); return {base:d, min:0, max:d, value:hi, error:null}; }
  if(strategy==='equal'){ var half=Math.floor(d/2); var hi2=half+Math.floor(rng()*(d-half)); return {base:d, min:half, max:d, value:hi2, error:null}; }
  if(strategy==='decorrelated'){
    var prev=opts.prev!=null?opts.prev:base;
    var sleep=Math.min(cap, prev*3 + Math.floor(rng()*base));
    return {base:d, min:Math.min(cap,prev*3), max:cap, value:sleep, prev:prev, error:null};
  }
  return {error:'unknown strategy'};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { expDelay:expDelay, backoff:backoff };
}
if (typeof window !== 'undefined') {
  window.BackoffForgePure = { expDelay:expDelay, backoff:backoff };
}
